settings.custom_liquid:
{% if request.page_type == 'page' and handle == 'listicle-1' or handle == 'listicle-2'or handle == 'listicle-3' %}
<style>
  /* Specific AI Announcement Bar ko hide karne ke liye */
  [class*="ai-announcement-bar"],
  [class*="ai-announcement-bar-container"],
  .ai-announcement-bar,
  .ai-announcement-bar-container {
    display: none !important;
    height: 0 !important;
    padding: 0 !important;
    margin: 0 !important;
    overflow: hidden !important;
    visibility: hidden !important;
  }

  /* Saath hi Header aur Footer ko bhi pakka block karne ke liye */
  #shopify-section-sections--header,
  #shopify-section-sections--footer,
  .header-wrapper,
  .footer {
    display: none !important;
  }

  /* Quiz ko top par laane ke liye padding zero */
  #MainContent {
    padding-top: 0 !important;
  }
background-image: url('https://cdn.shopify.com/s/files/1/0990/7119/7472/files/image_8e0f4889-232b-433d-b446-17a70694b461.webp?v=1776205475') !important;
</style>
{% endif %}
